# -*- coding: utf-8 -*-
"""
Translations for STm10001_02 (139 items)
Scene: Act Two - The City of Perfection
"""

TRANS_02 = {
    'STm10001_02.4': 'Hồi 2',
    'STm10001_02.5': 'Thành Phố Hoàn Hảo',
    'STm10001_02.6': 'Elis cứu bạn khỏi lũ rối, xua tan phần nào mối nghi ngờ của Alina. Những ngày tiếp theo trên đường đi, bạn và Elis dần trở nên thân thiết hơn qua những dòng chữ viết vụng trộm trong lòng bàn tay. Khi đặt chân đến Filanis, bạn bỗng cảm nhận được một thoáng quen thuộc mơ hồ…',
    'STm10001_02.60': 'Con Rối Vô Hồn',
    'STm10001_02.62': 'Kẽo kẹt, kẽo kẹt.',
    'STm10001_02.68': 'Lũ rối này dai như đỉa đói vậy. Alina rõ ràng đã chém chúng ra thành trăm mảnh vụn trước khi đuổi theo rồi, thế mà...',
    'STm10001_02.91': 'Bây giờ chúng lại tự bẻ tay bẻ chân của chính mình rồi chắp vá lại thành năm thân xác mới.',
    'STm10001_02.100': 'Cũng may là các chấn song này đủ kiên cố. Lũ này có đập phá điên cuồng đến đâu cũng chẳng để lại nổi một vết xước.',
    'STm10001_02.103': 'Cứ theo đà này... mình sẽ hoàn toàn an toàn trong này cho đến khi... chết đói.',
    'STm10001_02.105': 'Nhưng nếu chẳng có ai tới cứu, mình sẽ chết đói ở đây thật mất.',
    'STm10001_02.108': 'Được rồi, hoảng loạn lúc này chẳng giải quyết được gì. Phải nhớ lại mọi chuyện từ đầu xem nào.',
    'STm10001_02.114': 'Mình nhớ là...==W== mình đã cố sử dụng năng lực "đi lại nước cờ" để đánh bại Angie. Để tìm ra một lối thoát mà không ai phải bỏ mạng.',
    'STm10001_02.122': 'Nhưng điều đó đồng nghĩa với việc vứt bỏ tính mạng của chính mình. Nếu không có Vita dùng Ngai Vàng đỡ đòn hiểm đó, chắc mình đã mất mạng từ lâu rồi.',
    'STm10001_02.127': 'Ngai Vàng đã vỡ vụn. Khi tỉnh lại, mình thấy mình bị nhốt trong Phòng Trắng, không một bóng dáng nhân viên Cự Tháp nào quanh đây. Nơi đó chỉ là một khoảng hư vô bất tận.',
    'STm10001_02.128': 'Mình cứ bước đi mãi... bước đi cho đến khi tâm trí dần tê liệt. Rồi mình nghe thấy một giọng nói quen thuộc, và đẩy mở cánh cửa tiếp theo.',
    'STm10001_02.137': 'Để rồi bị tống thẳng tới chốn này.==W== Cảm giác chẳng khác nào khoảnh khắc tỉnh giấc trên Ốc Đảo May Mắn năm xưa, chỉ có điều...',
    'STm10001_02.141': 'Noya lại là một Dạ Hành Giả,==W== Iris thì hóa thành Thánh Nữ Sa Ngã,==W== còn Amber... thì chẳng thấy tăm hơi đâu cả.',
    'STm10001_02.148': '... Đây là một giấc mơ sao? Không, làm sao người ta có thể mơ thấy những điều mình chưa từng biết chứ.',
    'STm10001_02.149': 'Một ảo ảnh bên trong Phòng Trắng ư? Hay là một thế giới hoàn toàn khác? Mình thực sự chịu chết.',
    'STm10001_02.150': 'Nhưng điều đó không quan trọng. Mình đã tìm thấy lối thoát trong Phòng Trắng, nghĩa là mình vẫn chưa thua cuộc.',
    'STm10001_02.152': 'Dù bị chặt đầu chẳng phải trải nghiệm dễ chịu gì, nhưng mình vẫn lách qua được cánh cửa định mệnh đó thôi.',
    'STm10001_02.155': 'Dù có là ngõ cụt đi chăng nữa, ắt hẳn vẫn sẽ có lối ra. Vì mọi người, và vì cả Vita nữa... mình nhất định phải trở về!',
    'STm10001_02.162': 'Chuyện gì đang xảy ra thế? Sao cỗ xe lại rung lắc dữ dội thế này?',
    'STm10001_02.168': 'Lạch cạch, lạch cạch.',
    'STm10001_02.170': 'Khoan đã, sao tất cả bọn chúng lại dồn hết sang một bên xe thế kia?!',
    'STm10001_02.179': 'Răng rắc, lạch cạch.',
    'STm10001_02.182': 'Bọn chúng đang muốn lật nhào cỗ xe! Nếu xe đổ, chúng có thể thò tay qua song sắt tóm lấy mình!',
    'STm10001_02.186': 'Alina! Mau quay lại đây! Cái chuồng sắp sập rồi!',
    'STm10001_02.193': 'Hỡi Thần Ma Pháp, xin ban cho con ngọn thánh hỏa rực cháy...',
    'STm10001_02.196': 'Bóng hình kia...==W== Elis sao?',
    'STm10001_02.202': '... Hãy thiêu rụi khu rừng tà ác này!',
    'STm10001_02.204': 'H-Hỏa thuật ư?! Này, đừng nướng sống tôi chứ!',
    'STm10001_02.211': 'Ồ... Là phong nhận...',
    'STm10001_02.214': 'Thấy chưa hả Chủ nhân kính yêu của em? Rốt cuộc người vẫn luôn cần đến em mà thôi. Cô nàng Dạ Hành Giả kia vô tích sự thật đấy.',
    'STm10001_02.216': 'Cô ta chỉ thấy song sắt cứng cáp rồi đinh ninh bạo lực không phá nổi. Nhưng cô ta quên mất lũ này cũng có chút mưu mẹo. Tường đồng vách sắt có nghĩa lý gì nếu kẻ địch cứ việc trèo qua chứ.',
    'STm10001_02.217': 'Sao cô lại ở đây? Alina ở ngay gần đây thôi. Nếu cô ấy thấy cô, cô ấy sẽ bắt cô đấy. Mau đi đi.',
    'STm10001_02.220': 'Ồ? Chủ nhân thực sự đang lo lắng cho em sao. Em thấy vinh hạnh ghê đó nha.',
    'STm10001_02.224': 'Em là một Thánh Nữ Sa Ngã giết người không ghê tay cơ mà, người quên rồi à?',
    'STm10001_02.226': 'Người đã nhìn thấy mặt em, nghe thấy giọng em. Người không sợ em sẽ diệt khẩu nhân chứng duy nhất này sao?',
    'STm10001_02.228': 'Nếu cô đến để giết người diệt khẩu, cô đã chẳng cứu tôi làm gì. Cứ để mặc lũ rối ra tay chẳng phải tiện hơn nhiều sao.',
    'STm10001_02.229': 'Hơn nữa... Cô có thể là Thánh Nữ Sa Ngã thật, nhưng tôi không nghĩ cô sẽ giết người chỉ để xóa dấu vết đâu.',
    'STm10001_02.230': 'Thú vị thật đấy. Người mới tỉnh lại nửa tiếng trước, chúng ta cũng chỉ vừa mới gặp nhau. Lòng tin này từ đâu mà ra vậy?',
    'STm10001_02.233': 'Đừng nói là... người mê đắm nhan sắc của em rồi đấy nhé, hay là người thích nghe em ngọt ngào gọi hai tiếng Chủ nhân?',
    'STm10001_02.235': 'Bởi vì==W== tôi không đời nào tin một người có gương mặt giống hệt Iris lại là kẻ sát nhân...==W== Haizz. Nhưng nói thẳng câu đó ra mồm thì ai mà tin cho nổi.',
    'STm10001_02.240': 'Khụ. Không phải vì nhan sắc. Mà là vì cách hành sự của cô.',
    'STm10001_02.241': 'Không phải vì nhan sắc sao? Em hiểu rồi. Người bị em hớp hồn rồi chứ gì. Chỉ là người có lý do khác để tin tưởng em thôi.',
    'STm10001_02.242': 'Giờ thì em tò mò rồi đấy. Rốt cuộc hành động nào của em đã làm lộ tẩy thế?',
    'STm10001_02.243': 'Chà... Cái tính cách nghịch ngợm láu lỉnh này chẳng giống Iris chút nào. Tốt nhất là mình cứ nói toẹt ra cho cô ấy hiểu.',
    'STm10001_02.244': 'Cô là một ma pháp sư hùng mạnh. Nếu cô là kẻ giết người tàn nhẫn, cô việc gì phải lôi một kẻ mất trí nhớ ngơ ngác vào vở kịch giả mạo thân phận này.',
    'STm10001_02.246': 'Alina là một người lão luyện. Cô ấy vạch trần câu trả lời của tôi chỉ trong vài giây. Đối đầu với một đối thủ như thế, đánh lén bằng ma pháp mới là lựa chọn tối ưu nhất của cô.',
    'STm10001_02.247': 'Khi chúng ta bước ra ngoài xe, cô đúng là đã bí mật bố trí ma pháp trận. Thế nhưng đó chỉ là ma pháp gia tốc, hoàn toàn không gây sát thương.',
    'STm10001_02.249': 'Thói quen thì khó bỏ lắm. Cô luôn tránh làm người khác bị thương, và rõ ràng cô đã cố hết sức để tôi không bị cuốn vào vòng nguy hiểm. Cô căn bản không phải kẻ thủ ác máu lạnh.',
    'STm10001_02.252': 'Chậc. Đúng là một ngày kỳ lạ. Đầu tiên là một Dạ Hành Giả sắc sảo, giờ lại đến một Chủ nhân ra sức uốn lưỡi để chứng minh em vô tội.',
    'STm10001_02.255': 'Thôi chuyện của em nói thế đủ rồi. Chúng ta phải chuồn mau thôi.',
    'STm10001_02.264': 'Cô định cướp luôn cả cỗ xe này sao?!',
    'STm10001_02.266': 'Chính xác. Để xem cô nàng Dạ Hành Giả kia đuổi theo kiểu gì. Cứ để cô ta ở lại khu rừng này mà chơi đùa với đống sắt vụn cả đêm đi.',
    'STm10001_02.268': 'Ồ hố, lại có chướng ngại vật cản đường này.',
    'STm10001_02.271': 'Hỡi Thần Ma Pháp, xin ban cho con ngọn thánh hỏa rực cháy... Hãy thiêu rụi khu rừng tà ác này!',
    'STm10001_02.272': 'Đúng ma pháp rồi, nhưng đọc sai thần chú. Thói quen thi triển của cô nàng này kỳ quặc thật...',
    'STm10001_02.278': 'Khoan đã, mặt của lũ rối vừa đổi màu đấy ư?',
    'STm10001_02.283': 'Phong nhận... biến mất rồi sao?! Trên người chúng có kết giới kháng gió ư?!',
    'STm10001_02.285': 'Thế thì đỡ chiêu này xem!',
    'STm10001_02.286': 'Hỡi Thần Ma Pháp, xin hãy để đôi cánh nhanh nhẹn nhất của rừng sâu nghe theo mệnh lệnh của con. Hãy thanh tẩy thế giới ồn ã này!',
    'STm10001_02.296': 'S-Sao có thể như thế được? Chẳng ai lại lãng phí hai loại kết giới khác nhau lên đống phế liệu cả!==W== Khoan đã... Không chỉ là kết giới. Chúng đang nuốt chửng ma lực của mình!',
    'STm10001_02.299': 'Elis, cẩn thận!',
    'STm10001_02.304': 'Ư... Ma pháp của em vô dụng rồi. Chúng ta bị bao vây rồi.',
    'STm10001_02.305': 'Vào trong này mau! Cái lồng sắt sẽ chặn được chúng!',
    'STm10001_02.306': 'Không được. Nếu em mở cửa bây giờ, chúng sẽ ùa vào trong mất,==W== lúc đó cả hai chúng ta đều sẽ chết...',
    'STm10001_02.308': 'Lấy nền tảng linh hồn ta làm móng, lấy thần phách ta làm vữa... Ta phong ấn chiếc lồng của Chủ nhân. Hãy chống chọi bão giông, đứng vững trước cuồng phong, kiên cường qua lửa bỏng...',
    'STm10001_02.311': 'Elis, cô đang làm cái trò gì thế?!',
    'STm10001_02.313': 'Khó khăn lắm em mới gặp được một người hiểu mình. Em sẽ không để anh phải chết ngày hôm nay đâu, Tu Giả. Đây là tất cả chút ma lực còn sót lại của em. Nhận lấy đi.',
    'STm10001_02.316': 'Kết giới này chắc sẽ trụ được... Ít nhất là cho đến khi Dạ Hành Giả quay lại...==W==',
    'STm10001_02.331': 'Diễm Hỏa Rực Rỡ!',
    'STm10001_02.347': 'Bọn chúng đột nhiên trở nên kiên cố hơn. Mình không nhận ra loại ma pháp bảo hộ này...',
    'STm10001_02.348': 'Alina, thu hồi ma pháp lại mau! Chúng đang hấp thụ ma lực từ thanh kiếm của cô đấy!',
    'STm10001_02.349': 'A, tôi hiểu rồi.==W== Vậy thì tôi sẽ chém nát chúng bằng kiếm thuật thuần túy!',
    'STm10001_02.357': 'Đúng như tôi nghĩ. Cách này dễ dàng hơn nhiều.',
    'STm10001_02.359': 'Tránh xa cỗ xe ra mau!',
    'STm10001_02.366': 'Đây là nhát kiếm kết liễu!',
    'STm10001_02.373': 'Thật không thể tin nổi... Cô ấy chém gục năm mươi,==W== không, ít nhất cũng phải một trăm con rối chỉ bằng kiếm thuật đơn thuần thôi sao?!',
    'STm10001_02.374': 'Thưa ==SEX12== Tu Giả, ngài có sao không? Có bị thương ở đâu không?',
    'STm10001_02.375': 'Tôi ở trong xe an toàn rồi. Mau đi tìm Elis đi! Lũ rối vừa vùi lấp cô ấy rồi!',
    'STm10001_02.380': 'C-Chủ nhân, em không sao.',
    'STm10001_02.381': 'Đừng lo. <color=#3faeae>Nô lệ</color> của ngài cũng biết thân biết phận, đã nhanh trí chui xuống dưới đống đổ nát ẩn nấp khi tôi vung kiếm rồi.',
    'STm10001_02.384': 'Cô cũng khéo nói ghê nhỉ! Nhát chém cuối cùng suýt nữa thì phạt bay đầu tôi đấy!',
    'STm10001_02.385': 'Khoan đã. Cô vừa gọi tôi là gì cơ?',
    'STm10001_02.386': 'Tôi đã kiểm tra lũ rối trong rừng rồi. Không phải ma pháp của cô kích hoạt chúng.==W== Hơn nữa, tôi cũng đã thấy những gì cô làm...',
    'STm10001_02.387': 'Ngay trong khoảnh khắc cận kề cái chết, cô đã dốc cạn chút ma lực cuối cùng để tạo kết giới bảo vệ cho Tu Giả. Một Thánh Nữ Sa Ngã sẽ không bao giờ làm điều đó. Chỉ có một nô lệ tuyệt đối trung thành mới hành động như vậy.',
    'STm10001_02.388': 'Cô vẫn có thể là Thánh Nữ Sa Ngã ẩn mình sau lớp ngụy trang tinh vi, nhưng chân tướng đó giờ đã vượt quá quyền phán xét phàm trần của tôi rồi.',
    'STm10001_02.389': 'Tôi sẽ đưa cả hai người tới Filanis. Người bảo hộ của tôi,==W== Chấp Chính Quan <color=#3faeae>Olympia</color> vĩ đại, sẽ phán xét thân phận và định đoạt số phận của hai người.',
    'STm10001_02.391': 'Ba ngày sau.',
    'STm10001_02.396': '==A-2==Sau khi Alina đột ngột dừng cuộc thẩm vấn, chúng tôi tiếp tục lên đường.==P====RT====RT====A-1==Trên danh nghĩa, Elis vẫn là một kẻ tội đồ còn tôi là tẩu phạm tình nghi. Thế nhưng Alina lại đối đãi với chúng tôi hệt như một Tu Giả Tập Sự cùng thị giả của ==SEX3==, dành trọn cho chúng tôi mọi sự kính trọng tương xứng với thân phận ấy.==P====RT====RT====A-1==Thậm chí ba bữa ăn mỗi ngày của chúng tôi còn ngon lành hơn lương khô của cô ấy gấp bội phần.',
    'STm10001_02.397': 'Ngồi xóc nảy trên cỗ xe, tôi và Elis ngày càng trở nên thân thiết hơn,==RT==hình thành nên một phương thức trò chuyện vô cùng độc đáo.',
    'STm10001_02.400': '(Viết lại theo ngón tay em một lần nữa đi, ==PLAYER_NAME==! Một Tu Giả Tập Sự mà đến cả tên của ==SEX3== cũng không biết viết thì đúng là sơ hở chí mạng đấy.)',
    'STm10001_02.401': '(Hiểu rồi. Thử lại lần nữa nhé. Thế này đúng chưa?)',
    'STm10001_02.402': '(Tạm được thôi. Nét chữ của anh đúng là thảm họa.)',
    'STm10001_02.403': '(Từ giờ trở đi mọi việc ghi chép cứ để em lo hết. Dù sao thì việc đó cũng hoàn toàn khớp với thân phận nô lệ hầu cận.)',
    'STm10001_02.405': '(Hôm trước sao tự nhiên Alina lại bỏ ngang cuộc thẩm vấn thế? Cô có nghĩ ra lý do gì không?)',
    'STm10001_02.406': '(Em đoán được vài phần. Cô ta rất sắc sảo. Hẳn cô ta cũng nhận ra điểm mâu thuẫn giống như anh thôi. Cách hành xử của em chẳng giống chút nào với vị Thánh Nữ Sa Ngã mà cô ta được nghe kể.)',
    'STm10001_02.407': '(Hơn nữa, phong thái của anh trông cũng rất ra dáng quý tộc. Bắt giữ nhầm nô lệ riêng của anh sẽ khiến cô ta bị người bảo hộ khiển trách nặng nề đấy.)',
    'STm10001_02.408': '(Nhưng cô thực sự là vị Thánh Nữ bỏ trốn đó phải không?)',
    'STm10001_02.411': '(Giấu anh cũng chẳng để làm gì. Đúng là em đã bỏ trốn khỏi buổi tế lễ, nhưng suốt ba năm qua em chỉ ru rú trong tòa tháp gần Emor để nghiên cứu ma pháp thôi.)',
    'STm10001_02.412': '(Em hoàn toàn mù tịt về những tội ác kia. Đợi khi chúng ta ra khỏi đây, em sẽ cho anh xem nhật ký hàng ngày của em trong tòa tháp. Chúng sẽ chứng minh em trong sạch!)',
    'STm10001_02.414': '(Mấy ngày trước em đang ngủ say như chết trong tháp.)',
    'STm10001_02.416': '(Thế rồi cô nàng Dạ Hành Giả kia đùng đùng xông vào cầm theo bức chân dung định bắt em.)',
    'STm10001_02.418': '(Em chạy thục mạng qua Cự Tháp.==RT==Ngay lúc sắp kiệt sức ngã quỵ, em nhìn thấy một cỗ quan tài chạm trổ tinh xảo.)',
    'STm10001_02.421': '(Em định chui vào trốn, ai ngờ anh đã nằm sẵn trong đó rồi.)',
    'STm10001_02.422': '(Trông anh ăn mặc quý phái như vương công quý tộc, nên em mới nhận bừa anh là Tu Giả Tập Sự==RT==đang trong trạng thái hồi sinh mê man, còn em là nô lệ canh gác cho anh.)',
    'STm10001_02.423': '(Tự nguyện nhận mình là nô lệ... Có cần thiết phải làm đến mức đó không?)',
    'STm10001_02.424': '(Anh chẳng nhớ gì thật đấy à. Nô lệ là tài sản riêng. Nếu cô ta muốn bắt em, cô ta buộc phải có sự cho phép của chủ nhân trước.)',
    'STm10001_02.425': '(Chỉ cần em nhận là người của anh, cô ta bắt buộc phải xác minh quyền sở hữu của anh trước khi lôi em đi, bất kể em có là Thánh Nữ Sa Ngã hay không.)',
    'STm10001_02.426': '(Thế nên cô ta mới vác cả anh lẫn cỗ quan tài lên xe để điều tra đấy. Cô ta còn dọa nếu thân phận không khớp, cô ta sẽ khép em vào tội xúc phạm thi thể nữa cơ.)',
    'STm10001_02.427': '(Nhờ có anh mà em câu kéo thêm được bao nhiêu thời gian. Nếu không thì giờ em đã bị xích tay còng chân, đừng hòng vẽ nổi lấy nửa cái ma pháp trận.)',
    'STm10001_02.428': '(Mà nhắc mới nhớ, rốt cuộc anh là ai vậy? Sao anh lại nằm trong cỗ quan tài trên đỉnh Cự Tháp thế? Suốt ba năm qua em chưa từng thấy ai mò lên đó bao giờ.)',
    'STm10001_02.429': 'Mình sao có thể giải thích nổi chuyện bước qua Phòng Trắng để tới thế giới này được chứ... Đành phải kể tóm tắt đại khái cho cô ấy nghe vậy.',
    'STm10001_02.431': '(Tôi không phải Tu Giả gì đâu, và tôi đến từ một nơi rất, rất xa. Còn lý do vì sao tôi lại nằm trong cỗ quan tài đó trên Cự Tháp thì nói thật tôi cũng chịu chết.)',
    'STm10001_02.432': '(Chẳng sao cả. Trông anh ra dáng lắm rồi. Sẽ chẳng ai nghi ngờ vỏ bọc Tu Giả này đâu. Đến <color=#3faeae>Filanis</color> cứ để em lo liệu ăn nói, kẻo chúng ta bị lộ tẩy.)',
    'STm10001_02.434': '(Em sẽ tiếp tục đóng vai nô lệ của anh.==W== Nhưng nghiêm túc đấy, anh phải tỏ ra nghiêm khắc hơn với em một chút. Phải ra dáng quyền uy lên! Chẳng có ai lại đối xử với nô lệ dịu dàng như anh đâu.)',
    'STm10001_02.435': '(Với cô nàng Dạ Hành Giả kia cũng thế. Bỏ cái vẻ lịch thiệp nhã nhặn ấy đi, diễn thế lộ liễu lắm. Nhưng nếu cô ta phục vụ chu đáo, hãy ban thưởng cho cô ta thật hậu hĩnh.)',
    'STm10001_02.436': '(Tôi hiểu rồi. Tôi sẽ cố.)',
    'STm10001_02.437': '(Mà này... Cái trò viết chữ trong lòng bàn tay này có qua mắt được Alina thật không đấy?)',
    'STm10001_02.440': '(Chắc chắn rồi. Cô ta đang mải điều khiển ngựa mà. Với lại lỡ cô ta có nghi ngờ mờ ám, em cũng có thừa cách để đánh lạc hướng cô ta.)',
    'STm10001_02.443': 'Kính thưa các vị tội đồ. Chúng ta đã tới nơi rồi.',
    'STm10001_02.445': 'Chết thật, mải tập trung quá nên mình chẳng nhận ra cỗ xe đã dừng lại từ lúc nào.==W== Bị bắt quả tang rồi!',
    'STm10001_02.447': 'Á... Chủ nhân.',
    'STm10001_02.450': 'Người xoa như thế, cảm giác...==W== kỳ lạ lắm. Ngón tay của người...==W== có thể nhẹ nhàng hơn một chút được không?',
    'STm10001_02.453': 'Ờ... Đ-Được rồi. Ta biết rồi...',
    'STm10001_02.455': 'Cái cớ chữa cháy điên rồ quái quỷ gì thế này trời?!',
    'STm10001_02.456': 'Khụ. Những hành vi thân mật lập dị giữa chủ nhân và nô lệ cũng là chuyện thường thấy,==W== nhưng hai người nấn ná như vậy là đủ lâu rồi đấy. Đến lúc phải xuống xe rồi.',
    'STm10001_02.457': 'Xuống xe ư? Ở đây sao?',
    'STm10001_02.462': 'Xét đến thân phận được cho là của ngài, việc áp giải ngài vào thành trên một cỗ xe tù khi sự thật chưa sáng tỏ sẽ là một điều sỉ nhục.',
    'STm10001_02.463': 'Khụ. Cô chu đáo đến bất ngờ đấy. Chủ nhân của tôi là một Tu Giả danh giá. ==SEX1== tuyệt đối không thể diện kiến Chấp Chính Quan cùng với ==SEX8== trong bộ dạng nhếch nhác lem luốc thế này được.',
    'STm10001_02.464': 'Đúng vậy. Xét theo tình cảnh của hai người, tôi đã đặc biệt chọn một nhà tắm công cộng đóng cửa nghỉ tiếp khách hôm nay. Ở đây chỉ có ba chúng ta thôi.',
    'STm10001_02.465': 'Chu đáo thật đấy. Cơ mà chỗ này trông chẳng giống nơi có nhà tắm gì cả. Filanis thực sự hẻo lánh đến mức này sao?',
    'STm10001_02.466': 'Đây chưa phải nội thành Filanis. Nơi này chỉ là một khu định cư tự phát được dựng lên ở ngoại ô thôi.',
    'STm10001_02.471': 'Hãy nhìn đằng kia xem. Thành phố đang tỏa sáng rực rỡ dưới ánh mặt trời trên hòn đảo giữa hồ, được xây dựng bao quanh tòa tháp ấy.',
    'STm10001_02.473': 'Một Cự Tháp trên hòn đảo giữa hồ...==W== và cả cách bố trí đường xá quen thuộc này nữa.',
    'STm10001_02.474': 'Chẳng lẽ đây là...==W== Philae sao?',
    'STm10001_02.476': 'Đó mới chính là Filanis thực sự.==W== Thành Phố Hoàn Hảo vĩ đại.',
}
